import { cn } from "cn"

type StripStatus = "ok" | "degraded" | "down" | "none"

const statusColor: Record<StripStatus, string> = {
  ok: "var(--chart-2)",
  degraded: "var(--chart-4)",
  down: "var(--destructive)",
  none: "var(--muted)",
}

const statusLabel: Record<StripStatus, string> = { ok: "Operational", degraded: "Degraded", down: "Outage", none: "No data" }

/**
 * Status strip (uptime bars): one segment per period. Members: series
 * (segments), axes (start and end labels), legend (status key), tooltip
 * (native title + accessible label per segment).
 */
function ChartStatusStrip({
  label,
  segments,
  axes = true,
  legend = true,
  tooltip = true,
  className,
}: {
  label: string
  segments: { label: string; status: StripStatus }[]
  axes?: boolean
  legend?: boolean
  tooltip?: boolean
  className?: string
}) {
  const used = [...new Set(segments.map((s) => s.status))]
  return (
    <figure data-slot="chart" data-chart="status-strip" className={cn("flex w-full flex-col gap-2 text-xs", className)}>
      <ol aria-label={label} className="flex h-8 w-full gap-0.5">
        {segments.map((s, i) => {
          const text = `${s.label}: ${statusLabel[s.status]}`
          return (
            <li
              key={i}
              aria-label={text}
              title={tooltip ? text : undefined}
              className="min-w-0.5 flex-1 rounded-xs first:rounded-l-sm last:rounded-r-sm"
              style={{ background: statusColor[s.status] }}
            />
          )
        })}
      </ol>
      {axes && segments.length > 0 && (
        <div className="flex justify-between text-muted-foreground">
          <span>{segments[0].label}</span>
          <span>{segments[segments.length - 1].label}</span>
        </div>
      )}
      {legend && (
        <figcaption className="flex flex-wrap gap-3 text-muted-foreground">
          {used.map((s) => (
            <span key={s} className="flex items-center gap-1.5">
              <span aria-hidden="true" className="size-2 rounded-xs" style={{ background: statusColor[s] }} />
              {statusLabel[s]}
            </span>
          ))}
        </figcaption>
      )}
    </figure>
  )
}

export { ChartStatusStrip, type StripStatus }
